"""Writes suites/analyst-env.source.yaml from sql-analyst-env's public
tasks at the pinned commit (agent_eval/analyst_env.py). Then
`agent-eval generate-expected` turns it into the runnable suite against
copy A.

    uv run python scripts/build_analyst_env_source.py [--repo PATH]
"""

import argparse
from pathlib import Path

import yaml

from agent_eval import REPO_ROOT
from agent_eval.analyst_env import read_pinned_task_file, source_from_task_file

OUTPUT = REPO_ROOT / "suites" / "analyst-env.source.yaml"
HEADER = (
    "# GENERATED by scripts/build_analyst_env_source.py from sql-analyst-env's\n"
    "# tasks/public.yaml at the commit recorded below. Do not edit by hand.\n"
)


def main() -> None:
    parser = argparse.ArgumentParser(description="Write suites/analyst-env.source.yaml.")
    parser.add_argument("--repo", type=Path, default=REPO_ROOT.parent / "sql-analyst-env")
    repo: Path = parser.parse_args().repo
    source = source_from_task_file(read_pinned_task_file(repo))
    body = yaml.safe_dump(source, sort_keys=False, width=100, allow_unicode=True)
    OUTPUT.write_text(HEADER + body, encoding="utf-8")
    print(f"wrote {OUTPUT.relative_to(REPO_ROOT)}: {len(source['tasks'])} tasks")


if __name__ == "__main__":
    main()
